trigger-summary-format.implementation:
def format_triggers_for_prompt(triggers: List[Dict]) -> Optional[str]:
    if not triggers:
        return None

    lines = []
    for idx, trigger in enumerate(triggers, 1):
        intent_name = trigger.get("intent_name", "Unnamed trigger")

        # Format schedule or condition
        if trigger["trigger_type"] == "scheduled":
            schedule = trigger["schedule"]
            desc = format_schedule_human_readable(schedule)
        elif trigger["trigger_type"] == "condition":
            condition = trigger["condition"]
            desc = condition.get("expression", "Condition-based")

        # Format last fired
        last_fired = trigger.get("last_fired_at")
        if last_fired:
            fired_str = format_relative_time(last_fired)
        else:
            fired_str = "Never fired yet"

        lines.append(f'{idx}. "{intent_name}" - {desc} - Last fired: {fired_str}')

    return "\n".join(lines)
